-- Патч 27.11.2026 (4): новые фото Luna. Только поверх старых фото из каталога — можно запускать повторно.
update public.products set data = jsonb_set(data, '{photos}', '[{"src": "img/luna_choc_1.jpg", "color": "Шоколадный"}, {"src": "img/luna_choc_2.jpg", "color": "Шоколадный"}, {"src": "img/luna_choc_3.jpg", "color": "Шоколадный"}, {"src": "img/luna_choc_4.jpg", "color": "Шоколадный"}, {"src": "img/luna_black_1.jpg", "color": "Чёрный"}, {"src": "img/luna_black_2.jpg", "color": "Чёрный"}, {"src": "img/luna_black_3.jpg", "color": "Чёрный"}, {"src": "img/luna_black_4.jpg", "color": "Чёрный"}, {"src": "img/luna_black_5.jpg", "color": "Чёрный"}]'::jsonb) where id = 'luna' and (data->'photos')::text like '%p21_%';
select id, jsonb_array_length(data->'photos') as фото from public.products where id in ('alou', 'infinity', 'luna', 'valencia', 'yosh') order by id;
